// Time-sensitive notes for restaurants that already exist in the protected catalogue. atelier-guidance.js is
// hash-pinned, so these are added here, only when no alert exists yet, and never overwrite an original entry.
const VENUE_ADDITION_EXISTING_ALERTS={
r12:{en:"CHECKED 2026-10-25 (official site): lunch 11:30–14:00, dinner 17:00–22:00; closed Sundays, Mondays and year-end/New Year. Same-day cancellation fee ¥5,000 (lunch) / ¥10,000 (dinner). Reconfirm before booking.",ja:"2026-10-25確認（公式）：ランチ11:30〜14:00、ディナー17:00〜22:00。日・月曜と年末年始は休み。当日キャンセル料はランチ5,000円／ディナー10,000円。予約前に再確認。",ko:"2026-10-25 확인(공식): 점심 11:30~14:00, 저녁 17:00~22:00. 일·월요일과 연말연시 휴무. 당일 취소 수수료 점심 5,000엔/저녁 10,000엔. 예약 전 재확인."},
r24:{en:"SCHEDULED CLOSURES (official, checked 2026-10-25): Wednesdays Oct 28, Nov 4, 11, 18 and 25, 2026, plus New Year's Eve and New Year's Day. Reconfirm before booking.",ja:"休業予定（公式、2026-10-25確認）：2026年10月28日、11月4・11・18・25日（いずれも水曜）、および大晦日・元日。予約前に再確認。",ko:"휴업 예정(공식, 2026-10-25 확인): 2026년 10월 28일, 11월 4·11·18·25일(모두 수요일) 및 12월 31일·1월 1일. 예약 전 재확인."}
};

// Merge into the shared runtime registries (all declared by earlier classic scripts).
// Original venues are never touched. For an added ID, any pre-existing entry is an orphan
// (it belonged to no venue — e.g. a stale "Spa Izumi" alias under w08) and is replaced.
(function mergeVenueAdditions(){
 const original=new Set(DATA.map(r=>r.id)),added=new Set();
 for(const r of VENUE_ADDITIONS){
  if(original.has(r.id)||added.has(r.id)||!CATS.includes(r.category))continue;
  DATA.push(r);added.add(r.id);
  ROWS_BY_CATEGORY.get(r.category).push(r);
 }
 const put=(target,entries)=>{for(const [id,v] of Object.entries(entries))if(added.has(id))target[id]=v};
 put(VERIFIED_SOURCES,VENUE_ADDITION_SOURCES);
 put(SOURCE_SCOPE,VENUE_ADDITION_SOURCE_SCOPE);
 put(PLACE_ALIASES,VENUE_ADDITION_ALIASES);
 put(CONCIERGE_GUIDANCE,VENUE_ADDITION_GUIDANCE);
 for(const [id,v] of Object.entries(VENUE_ADDITION_EXISTING_ALERTS))if(original.has(id)&&!VENUE_ALERTS[id])VENUE_ALERTS[id]=v;
 for(const [area,v] of Object.entries(VENUE_ADDITION_AREA_ALIASES))if(!SEARCH_ALIASES[area])SEARCH_ALIASES[area]=v;
})();
